        (
            Bounds::new(
                point(bounds.left(), bounds.top() + BEVEL),
                size(BEVEL, side),
            ),
            light,
        ),
        (
            Bounds::new(
                point(bounds.left(), bounds.bottom() - BEVEL),
                size(width, BEVEL),
            ),
            shade,
        ),
        (
            Bounds::new(
                point(bounds.right() - BEVEL, bounds.top() + BEVEL),
                size(BEVEL, side),
            ),
            shade,
        ),
    ]
}

